package com.bank.payrollcost;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PayrollCostDemo {
    private static final Logger log = Logger.getLogger("PayrollCost");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", "Trading", new BigDecimal("1200000")),
            new Employee("Sneha", "Trading", new BigDecimal("1500000")),
            new Employee("Priya", "Risk", new BigDecimal("900000")),
            new Employee("Neha", "Risk", new BigDecimal("650000")));
        PayrollService service = new PayrollService();

        Map<String, BigDecimal> totals = service.totalSalaryByDepartment(employees);
        totals.forEach((dept, total) -> log.info(() -> dept + " total salary = " + total));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final BigDecimal salary;   // money is BigDecimal, never double
    Employee(String name, String department, BigDecimal salary) {
            this.name = name;
            this.department = department
            this.salary = salary;
    }
    String getDepartment() { return department; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/PayrollService.java ───
class PayrollService {
    // groupingBy department, reducing each group's salaries with BigDecimal::add
    Map<String, BigDecimal> totalSalaryByDepartment(List<Employee> employees) {
        return employees.stream().collect(
            java.util.stream.Collectors.groupingBy(
                Employee::getDepartment,
                java.util.stream.Collectors.reducing(
                    BigDecimal.ZERO,        // identity
                    Employee::getSalary,    // mapper → BigDecimal
                    BigDecimal::add)));     // associative combiner
    }
}
